    ('CTCAC_HOTMA_STUDENT_FINANCIAL_AID_VERIFICATION','https://www.treasurer.ca.gov/sites/default/files/ctcac/Verification%20of%20Student-Financial-Assistance-FINAL-2026.pdf','2026-08-29T06:20:54.545Z',287394::bigint,'a17093602086a611085e362691f2a7562b2b676dfa173fc8eac71d4dacc48c97','HOTMA Financial Aid Verification Form','HOTMA_HOUSEHOLD','income_evidence_template','{"trigger":"STUDENT_FINANCIAL_AID_REPORTED","applicability":null,"mandatoryFrom":"2027-01-01","preMandatoryApplicability":"DOCUMENTED_PARTIAL_OR_FULL_HOTMA_ELECTION","finalUrl":"https://www.treasurer.ca.gov/sites/default/files/ctcac/Verification%20of%20Student-Financial-Assistance-FINAL-2026.pdf","contentType":"application/pdf","etag":"\"6a270917-462a2\"","lastModified":"Mon, 08 Jun 2026 18:25:27 GMT"}')
  ) as capture(source_type,source_url,retrieved_at,byte_size,sha256,title,validation_scope,rule_role,applicability)
  on conflict (state_code, inventory_generated_at, scope, source_url) do update set
    source_type = excluded.source_type,
    authority_name = excluded.authority_name,
    official_domain = excluded.official_domain,
    origin_file = excluded.origin_file,
    candidate_status = excluded.candidate_status,
    agent_verification_status = case
      when public.state_rule_source_candidates.agent_verification_status in ('verified','rejected')
        then public.state_rule_source_candidates.agent_verification_status
      else 'captured_unvalidated'
    end,
    exact_bytes_captured = true,
    source_sha256 = excluded.source_sha256,
    retrieved_at = excluded.retrieved_at,
    verification_evidence = public.state_rule_source_candidates.verification_evidence || excluded.verification_evidence,
    compliance_activation_allowed = false,
    updated_at = now();

  select count(*) into reconciled
  from public.state_rule_source_candidates
  where state_code = 'CA'
    and origin_file = 'california-ctcac-compliance-forms.json'
    and exact_bytes_captured
    and source_sha256 is not null;
  if reconciled <> 26 then
    raise exception 'California form capture reconciliation expected 26 sources, found %', reconciled;
  end if;

  update public.state_rule_pack_candidates pack
  set status = 'agent_verification_in_progress',
      source_candidate_count = (select count(*) from public.state_rule_source_candidates source where source.state_code = 'CA'),
      blocked_source_count = (select count(*) from public.state_rule_source_candidates source where source.state_code = 'CA' and source.agent_verification_status = 'blocked'),
      candidate_manifest = pack.candidate_manifest || jsonb_build_object(
        'source_count', (select count(*) from public.state_rule_source_candidates source where source.state_code = 'CA'),
        'ctcac_form_link_count', 24,
        'ctcac_controlled_capture_count', 26,
        'ctcac_forms_manifest', 'config/california-ctcac-compliance-forms.json',
        'independent_validation_required', true
      ),
      compliance_activation_allowed = false,
      updated_at = now()
  where state_code = 'CA';
end
